    highest_code = 0
    for sku in SKU.objects.select_related("product").iterator():
        specification = (sku.specification or "").strip()
        display_name = " ".join(part for part in [sku.product.name, specification] if part)
        display_name = display_name or sku.product.name or sku.sku
        description_cn = "，".join(part for part in [sku.product.name, specification] if part) or display_name
        description_en = ", ".join(part for part in [sku.product.name_en or sku.product.name, specification] if part) or display_name
